package com.hibernate.ecommerce.mapper;import com.hibernate.ecommerce.dto.OrderDTO;import com.hibernate.ecommerce.dto.OrderdetailsDTO;import com.hibernate.ecommerce.model.Client;import com.hibernate.ecommerce.model.Order;import com.hibernate.ecommerce.model.Orderdetails;import com.hibernate.ecommerce.model.Product;import java.util.stream.Collectors;public class OrderMapper {    public static OrderDTO toDTO(Order order){        if(order == null) return null;        var orderdetailsList = order.getOrderdetails().stream()                .map(dto ->                        OrderdetailsDTO.builder()                                .id(dto.getId())                                .orderId(dto.getOrder().getId())                                .productId(dto.getProduct().getId())                                .price(dto.getPrice())                                .quantity(dto.getQuantity())                                .build())                .collect(Collectors.toList());        return OrderDTO.builder()                .id(order.getId())                .clientId(order.getClient().getId())                .state(order.getState())                .orderdetails(orderdetailsList)                .build();    }    public static Order toEntity(OrderDTO dto, Client client, Order order, Product product){        if(dto == null) return null;        var orderdetailsdtoList = dto.getOrderdetails().stream()                .map(orderdetail -> Orderdetails.builder()                        .id(orderdetail.getId())                        .order(order)                        .product(product)                        .price(orderdetail.getPrice())                        .quantity(orderdetail.getQuantity())                        .build())                .collect(Collectors.toList());        return Order.builder()                .id(dto.getId())                .state(dto.getState())                .client(client)                .orderdetails(orderdetailsdtoList)                .build();    }}